const value = msg.payload;
const date = typeof value === 'string' ? value.trim() : '';
const parsed = new Date(date);
if (!/^[1-9]\d{3}-\d{2}-\d{2}$/.test(date) ||
    Number.isNaN(parsed.getTime()) ||
    parsed.toISOString().slice(0, 10) !== date) {
    return [null, { payload: { error: 'Choose a valid entry date in YYYY-MM-DD format.' } }];
}
return [{ report: { date, page: 1, total: null, seen: [], recorded: 0, billable: 0 } }, null];

const authorization = env.get('TIMELODGE_AUTHORIZATION');
if (typeof authorization !== 'string' || !/^Bearer [\x21-\x7e]+$/.test(authorization)) {
    return [null, { payload: { error: 'Set TIMELODGE_AUTHORIZATION to Bearer followed by your time:read token.' } }];
}
const report = msg.report;
return [{
    report,
    url: 'https://timelodge.com/api/v1/time-entries?entry_date=' + report.date + '&page=' + report.page + '&per_page=100',
    followRedirects: false,
    requestTimeout: 10000
}, null];

function failure(error, extra = {}) {
    return [null, null, { payload: { error, ...extra } }];
}

const status = msg.statusCode;
if (status === 401 || status === 403) {
    return failure('TimeLodge denied access. Confirm the workspace has API access and the token has time:read.');
}
if (status === 429) {
    const retryAfter = String(msg.headers?.['retry-after'] ?? '');
    const delay = /^\d{1,5}$/.test(retryAfter) ? { retryAfterSeconds: Number(retryAfter) } : {};
    return failure('TimeLodge rate limit reached. Retry the summary later.', delay);
}
if (status !== 200) {
    return failure('TimeLodge could not return time entries. Check access and try again.');
}

const { data, meta } = msg.payload ?? {};
const report = msg.report;
const limit = 100;
if (!Array.isArray(data) ||
    meta?.current_page !== report.page ||
    meta.per_page !== limit ||
    !Number.isSafeInteger(meta.total) ||
    meta.total < 0 ||
    meta.last_page !== Math.max(1, Math.ceil(meta.total / limit)) ||
    meta.last_page < report.page ||
    data.length !== Math.min(limit, Math.max(0, meta.total - (report.page - 1) * limit)) ||
    (report.total !== null && meta.total !== report.total)) {
    return failure('TimeLodge returned inconsistent pagination. Retry when entries have stopped changing.');
}
if (meta.last_page > 100) {
    return failure('This flow can summarise up to 10,000 entries for one date.');
}
report.total = meta.total;
const seen = new Set(report.seen);
for (const entry of data) {
    if (typeof entry?.id !== 'string' ||
        entry.id === '' ||
        seen.has(entry.id) ||
        !Number.isSafeInteger(entry.duration_seconds) ||
        entry.duration_seconds < 0 ||
        typeof entry.billable !== 'boolean') {
        return failure('TimeLodge returned an invalid or duplicate entry. Retry the summary.');
    }
    seen.add(entry.id);
    report.recorded += entry.duration_seconds;
    if (entry.billable) {
        report.billable += entry.duration_seconds;
    }
}
if (!Number.isSafeInteger(report.recorded)) {
    return failure('The total time exceeds the range this flow can summarise.');
}
if (report.page < meta.last_page) {
    return [{ report: { ...report, page: report.page + 1, seen: [...seen] } }, null, null];
}
return [null, {
    payload: {
        entryDate: report.date,
        entryCount: seen.size,
        recordedSeconds: report.recorded,
        billableSeconds: report.billable
    }
}, null];
